/// Parse a single line, stripping optional `export` prefix.
fn parse_line(line: &str) -> Option<(String, String)> {
    let line = line.strip_prefix("export ").unwrap_or(line);
    let eq_pos = line.find('=')?;
    let key = line[..eq_pos].trim().to_string();
    let raw_value = line[eq_pos + 1..].trim();

    let value = if raw_value.starts_with('"') && raw_value.ends_with('"') && raw_value.len() >= 2
    {
        // Double-quoted: strip quotes and process escape sequences
        Self::process_double_quoted(&raw_value[1..raw_value.len() - 1])
    } else if raw_value.starts_with('\'') && raw_value.ends_with('\'') && raw_value.len() >= 2
    {
        // Single-quoted: strip quotes, keep content literal
        raw_value[1..raw_value.len() - 1].to_string()
    } else {
        // Unquoted: strip inline comments
        Self::strip_inline_comment(raw_value)
    };

    Some((key, value))
}

/// Process escape sequences in a double-quoted value.
fn process_double_quoted(value: &str) -> String {
    let mut result = String::with_capacity(value.len());
    let mut chars = value.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('n') => result.push('\n'),
                Some('t') => result.push('\t'),
                Some('\\') => result.push('\\'),
                Some('"') => result.push('"'),
                Some(other) => {
                    result.push('\\');
                    result.push(other);
                }
                None => result.push('\\'),
            }
        } else {
            result.push(c);
        }
    }
    result
}

/// Strip an inline comment from an unquoted value.
fn strip_inline_comment(value: &str) -> String {
    if let Some(pos) = value.find(" #") {
        value[..pos].trim_end().to_string()
    } else {
        value.to_string()
    }
}

